package com.gotrrunetracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;

@ConfigGroup("gotrrunetracker")
public interface GotrRuneTrackerConfig extends Config
{
}

package com.gotrrunetracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.text.DecimalFormat;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class GotrRuneTrackerPanel extends PluginPanel
{
    private static final Color ACCENT =
            new Color(90, 170, 255);

    private static final Color MUTED =
            new Color(160, 160, 160);

    private static final Color ZERO_VALUE =
            new Color(120, 120, 120);

    private static final DecimalFormat AVERAGE_FORMAT =
            new DecimalFormat("0.0");

    private static final String[] RUNES =
            {
                    "Air",
                    "Mind",
                    "Water",
                    "Earth",
                    "Fire",
                    "Body",
                    "Cosmic",
                    "Chaos",
                    "Nature",
                    "Law",
                    "Death",
                    "Blood",
                    "Mist",
                    "Dust",
                    "Mud",
                    "Smoke",
                    "Steam",
                    "Lava"
            };

    private final Map<String, JLabel> currentGameLabels =
            new LinkedHashMap<>();

    private final Map<String, JLabel> sessionLabels =
            new LinkedHashMap<>();

    private final Map<String, JLabel> averageLabels =
            new LinkedHashMap<>();

    private final JLabel currentGameTotalLabel =
            createAmountLabel();

    private final JLabel sessionTotalLabel =
            createAmountLabel();

    private final JLabel averageTotalLabel =
            createAmountLabel();

    private final JLabel currentGameHeaderTotalLabel =
            new JLabel("0", SwingConstants.CENTER);

    private final JLabel gamesCompletedLabel =
            new JLabel("0", SwingConstants.CENTER);

    private final JButton newGameButton =
            new JButton("New Game");

    private final JButton resetSessionButton =
            new JButton("Reset Session");

    public GotrRuneTrackerPanel()
    {
        setLayout(new BorderLayout());

        setBorder(
                new EmptyBorder(
                        12,
                        12,
                        12,
                        12
                )
        );

        setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        JPanel mainPanel =
                new JPanel();

        mainPanel.setLayout(
                new BoxLayout(
                        mainPanel,
                        BoxLayout.Y_AXIS
                )
        );

        mainPanel.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        mainPanel.add(
                createHeaderPanel()
        );

        mainPanel.add(
                Box.createRigidArea(
                        new Dimension(0, 10)
                )
        );

        mainPanel.add(
                createRuneSection(
                        "Current Game",
                        currentGameLabels,
                        currentGameTotalLabel
                )
        );

        mainPanel.add(
                Box.createRigidArea(
                        new Dimension(0, 10)
                )
        );

        mainPanel.add(
                createRuneSection(
                        "Total Session",
                        sessionLabels,
                        sessionTotalLabel
                )
        );

        mainPanel.add(
                Box.createRigidArea(
                        new Dimension(0, 10)
                )
        );

        mainPanel.add(
                createRuneSection(
                        "Average per Completed Game",
                        averageLabels,
                        averageTotalLabel
                )
        );

        mainPanel.add(
                Box.createRigidArea(
                        new Dimension(0, 10)
                )
        );

        mainPanel.add(
                createButtonPanel()
        );

        add(
                mainPanel,
                BorderLayout.NORTH
        );

        styleButtons();
    }

    private JPanel createHeaderPanel()
    {
        JPanel headerPanel =
                new JPanel();

        headerPanel.setLayout(
                new BoxLayout(
                        headerPanel,
                        BoxLayout.Y_AXIS
                )
        );

        headerPanel.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        JLabel titleLabel =
                new JLabel(
                        "GOTR Rune Tracker",
                        SwingConstants.CENTER
                );

        titleLabel.setAlignmentX(
                CENTER_ALIGNMENT
        );

        titleLabel.setFont(
                titleLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                18f
                        )
        );

        titleLabel.setForeground(
                Color.WHITE
        );

        JPanel statsPanel =
                new JPanel(
                        new GridLayout(
                                1,
                                2,
                                8,
                                0
                        )
                );

        statsPanel.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        statsPanel.setBorder(
                new EmptyBorder(
                        10,
                        0,
                        0,
                        0
                )
        );

        statsPanel.setMaximumSize(
                new Dimension(
                        Integer.MAX_VALUE,
                        62
                )
        );

        statsPanel.add(
                createHeaderStat(
                        "Current Game",
                        currentGameHeaderTotalLabel
                )
        );

        statsPanel.add(
                createHeaderStat(
                        "Games Completed",
                        gamesCompletedLabel
                )
        );

        headerPanel.add(
                titleLabel
        );

        headerPanel.add(
                statsPanel
        );

        return headerPanel;
    }

    private JPanel createHeaderStat(
            String title,
            JLabel valueLabel)
    {
        JPanel panel =
                new JPanel();

        panel.setLayout(
                new BoxLayout(
                        panel,
                        BoxLayout.Y_AXIS
                )
        );

        panel.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        panel.setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createLineBorder(
                                ColorScheme.MEDIUM_GRAY_COLOR
                        ),
                        new EmptyBorder(
                                7,
                                4,
                                7,
                                4
                        )
                )
        );

        JLabel titleLabel =
                new JLabel(
                        title,
                        SwingConstants.CENTER
                );

        titleLabel.setAlignmentX(
                CENTER_ALIGNMENT
        );

        titleLabel.setForeground(
                MUTED
        );

        titleLabel.setFont(
                titleLabel
                        .getFont()
                        .deriveFont(
                                Font.PLAIN,
                                11f
                        )
        );

        valueLabel.setAlignmentX(
                CENTER_ALIGNMENT
        );

        valueLabel.setHorizontalAlignment(
                SwingConstants.CENTER
        );

        valueLabel.setForeground(
                Color.WHITE
        );

        valueLabel.setFont(
                valueLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                16f
                        )
        );

        panel.add(
                titleLabel
        );

        panel.add(
                Box.createRigidArea(
                        new Dimension(0, 3)
                )
        );

        panel.add(
                valueLabel
        );

        return panel;
    }

    private JPanel createRuneSection(
            String title,
            Map<String, JLabel> labelMap,
            JLabel totalLabel)
    {
        JPanel sectionPanel =
                new JPanel(
                        new BorderLayout(
                                0,
                                8
                        )
                );

        sectionPanel.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        sectionPanel.setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createLineBorder(
                                ColorScheme.MEDIUM_GRAY_COLOR
                        ),
                        new EmptyBorder(
                                10,
                                10,
                                10,
                                10
                        )
                )
        );

        JLabel sectionTitle =
                new JLabel(
                        title
                );

        sectionTitle.setFont(
                sectionTitle
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                14f
                        )
        );

        sectionTitle.setForeground(
                ACCENT
        );

        JPanel runeGrid =
                new JPanel(
                        new GridLayout(
                                0,
                                2,
                                8,
                                5
                        )
                );

        runeGrid.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        for (String runeName : RUNES)
        {
            addRuneRow(
                    runeGrid,
                    labelMap,
                    runeName
            );
        }

        JPanel totalPanel =
                new JPanel(
                        new GridLayout(
                                1,
                                2
                        )
                );

        totalPanel.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        totalPanel.setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createMatteBorder(
                                1,
                                0,
                                0,
                                0,
                                ColorScheme.MEDIUM_GRAY_COLOR
                        ),
                        new EmptyBorder(
                                8,
                                0,
                                0,
                                0
                        )
                )
        );

        JLabel totalTextLabel =
                new JLabel(
                        "Total"
                );

        totalTextLabel.setFont(
                totalTextLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD
                        )
        );

        totalTextLabel.setForeground(
                Color.WHITE
        );

        totalLabel.setFont(
                totalLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD
                        )
        );

        totalLabel.setForeground(
                Color.WHITE
        );

        totalPanel.add(
                totalTextLabel
        );

        totalPanel.add(
                totalLabel
        );

        sectionPanel.add(
                sectionTitle,
                BorderLayout.NORTH
        );

        sectionPanel.add(
                runeGrid,
                BorderLayout.CENTER
        );

        sectionPanel.add(
                totalPanel,
                BorderLayout.SOUTH
        );

        return sectionPanel;
    }

    private void addRuneRow(
            JPanel panel,
            Map<String, JLabel> labelMap,
            String runeName)
    {
        JLabel nameLabel =
                new JLabel(
                        runeName
                );

        nameLabel.setForeground(
                new Color(
                        220,
                        220,
                        220
                )
        );

        JLabel amountLabel =
                createAmountLabel();

        labelMap.put(
                runeName,
                amountLabel
        );

        panel.add(
                nameLabel
        );

        panel.add(
                amountLabel
        );
    }

    private JLabel createAmountLabel()
    {
        JLabel label =
                new JLabel(
                        "0",
                        SwingConstants.RIGHT
                );

        label.setForeground(
                ZERO_VALUE
        );

        return label;
    }

    private JPanel createButtonPanel()
    {
        JPanel buttonPanel =
                new JPanel(
                        new GridLayout(
                                1,
                                2,
                                8,
                                0
                        )
                );

        buttonPanel.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        buttonPanel.add(
                newGameButton
        );

        buttonPanel.add(
                resetSessionButton
        );

        return buttonPanel;
    }

    private void styleButtons()
    {
        newGameButton.setFocusPainted(
                false
        );

        resetSessionButton.setFocusPainted(
                false
        );
    }

    public void setNewGameAction(
            Runnable action)
    {
        newGameButton.addActionListener(
                event -> action.run()
        );
    }

    public void setResetSessionAction(
            Runnable action)
    {
        resetSessionButton.addActionListener(
                event -> action.run()
        );
    }

    public void updateTotals(
            Map<String, Integer> currentGame,
            Map<String, Integer> session,
            Map<String, Double> averages)
    {
        int currentTotal =
                updateIntegerLabels(
                        currentGameLabels,
                        currentGame
                );

        int sessionTotal =
                updateIntegerLabels(
                        sessionLabels,
                        session
                );

        double averageTotal =
                updateAverageLabels(
                        averageLabels,
                        averages
                );

        setIntegerLabel(
                currentGameTotalLabel,
                currentTotal
        );

        setIntegerLabel(
                sessionTotalLabel,
                sessionTotal
        );

        setAverageLabel(
                averageTotalLabel,
                averageTotal
        );

        currentGameHeaderTotalLabel.setText(
                Integer.toString(
                        currentTotal
                )
        );
    }

    public void updateGamesCompleted(
            int gamesCompleted)
    {
        gamesCompletedLabel.setText(
                Integer.toString(
                        gamesCompleted
                )
        );
    }

    private int updateIntegerLabels(
            Map<String, JLabel> labels,
            Map<String, Integer> values)
    {
        int total = 0;

        for (Map.Entry<String, JLabel> entry
                : labels.entrySet())
        {
            int value =
                    values.getOrDefault(
                            entry.getKey(),
                            0
                    );

            total += value;

            setIntegerLabel(
                    entry.getValue(),
                    value
            );
        }

        return total;
    }

    private double updateAverageLabels(
            Map<String, JLabel> labels,
            Map<String, Double> values)
    {
        double total = 0.0;

        for (Map.Entry<String, JLabel> entry
                : labels.entrySet())
        {
            double value =
                    values.getOrDefault(
                            entry.getKey(),
                            0.0
                    );

            total += value;

            setAverageLabel(
                    entry.getValue(),
                    value
            );
        }

        return total;
    }

    private void setIntegerLabel(
            JLabel label,
            int value)
    {
        label.setText(
                Integer.toString(
                        value
                )
        );

        label.setForeground(
                value == 0
                        ? ZERO_VALUE
                        : Color.WHITE
        );
    }

    private void setAverageLabel(
            JLabel label,
            double value)
    {
        label.setText(
                AVERAGE_FORMAT.format(
                        value
                )
        );

        label.setForeground(
                value == 0.0
                        ? ZERO_VALUE
                        : Color.WHITE
        );
    }
}

package com.gotrrunetracker;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.Varbits;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Text;
import net.runelite.api.TileItem;

@PluginDescriptor(
        name = "GOTR Rune Tracker",
        description = "Tracks runes crafted during Guardians of the Rift",
        tags = {"gotr", "guardians of the rift", "runecraft", "runes", "tracker"}
)
public class GotrRuneTrackerPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ClientToolbar clientToolbar;

    private GotrRuneTrackerPanel panel;
    private NavigationButton navigationButton;

    private final Map<Integer, String> runeNames = new LinkedHashMap<>();
    private final Map<Integer, Integer> previousRuneCounts = new HashMap<>();

    private final Map<String, Integer> currentGameTotals = new LinkedHashMap<>();
    private final Map<String, Integer> sessionTotals = new LinkedHashMap<>();
    private final Map<String, Integer> completedGameTotals = new LinkedHashMap<>();

    /*
     * Ground-rune pickups that should be ignored.
     *
     * Value = quantity currently available to ignore.
     */
    private final Map<Integer, Integer> pendingGroundPickups = new HashMap<>();

    /*
     * Expiry tick for each pending ground-rune pickup.
     *
     * This prevents a rune despawning somewhere nearby from suppressing
     * a legitimate crafted gain much later.
     */
    private final Map<Integer, Integer> pendingGroundPickupExpiry = new HashMap<>();

    private static final int GROUND_PICKUP_EXPIRY_TICKS = 3;

    private int gamesCompleted;
    private int lastCompletedGameTick = -1;

    private boolean gotrGameActive;
    private boolean waitingForNextGameStart;
    private boolean gotrHudWasVisible;

    private static final int[] RUNE_POUCH_TYPE_VARBITS =
            {
                    Varbits.RUNE_POUCH_RUNE1,
                    Varbits.RUNE_POUCH_RUNE2,
                    Varbits.RUNE_POUCH_RUNE3,
                    Varbits.RUNE_POUCH_RUNE4,
                    Varbits.RUNE_POUCH_RUNE5,
                    Varbits.RUNE_POUCH_RUNE6
            };

    private static final int[] RUNE_POUCH_AMOUNT_VARBITS =
            {
                    Varbits.RUNE_POUCH_AMOUNT1,
                    Varbits.RUNE_POUCH_AMOUNT2,
                    Varbits.RUNE_POUCH_AMOUNT3,
                    Varbits.RUNE_POUCH_AMOUNT4,
                    Varbits.RUNE_POUCH_AMOUNT5,
                    Varbits.RUNE_POUCH_AMOUNT6
            };

    @Provides
    GotrRuneTrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GotrRuneTrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        initialiseRunes();
        initialiseTotals();

        SwingUtilities.invokeLater(() ->
        {
            panel = new GotrRuneTrackerPanel();
            panel.setNewGameAction(this::startNewGame);
            panel.setResetSessionAction(this::resetSession);

            refreshPanel();

            navigationButton = NavigationButton.builder()
                    .tooltip("GOTR Rune Tracker")
                    .icon(loadIcon())
                    .priority(5)
                    .panel(panel)
                    .build();

            clientToolbar.addNavigation(navigationButton);
        });

        clientThread.invokeLater(() ->
        {
            gotrGameActive = false;
            waitingForNextGameStart = false;
            gotrHudWasVisible = isGotrHudVisible();

            snapshotCurrentRunes();
        });
    }

    @Override
    protected void shutDown()
    {
        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
        }

        navigationButton = null;
        panel = null;

        previousRuneCounts.clear();
        currentGameTotals.clear();
        sessionTotals.clear();
        completedGameTotals.clear();

        pendingGroundPickups.clear();
        pendingGroundPickupExpiry.clear();

        gamesCompleted = 0;
        lastCompletedGameTick = -1;

        gotrGameActive = false;
        waitingForNextGameStart = false;
        gotrHudWasVisible = false;
    }

    private boolean isGotrHudVisible()
    {
        Widget gotrDisplay = client.getWidget(InterfaceID.GotrHud.CONTENT);

        return gotrDisplay != null
                && !gotrDisplay.isHidden();
    }

    private boolean isBankOpen()
    {
        return client.getWidget(InterfaceID.BANKMAIN, 0) != null;
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        expireOldGroundPickups();

        boolean hudVisible = isGotrHudVisible();

        if (!gotrGameActive && hudVisible)
        {
            int currentTick = client.getTickCount();

            if (lastCompletedGameTick == -1
                    || currentTick - lastCompletedGameTick > 2)
            {
                beginGameTracking();
            }
        }

        if (gotrGameActive
                && hudVisible
                && !gotrHudWasVisible)
        {
            snapshotCurrentRunes();
        }

        /*
         * Rune-pouch quantities can change without the inventory container
         * itself changing, so check once per game tick while active.
         */
        if (gotrGameActive)
        {
            processRuneChanges();
        }

        gotrHudWasVisible = hudVisible;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.INVENTORY.getId())
        {
            return;
        }

        if (isBankOpen())
        {
            snapshotCurrentRunes();
            return;
        }

        if (!gotrGameActive)
        {
            snapshotCurrentRunes();
            return;
        }

        processRuneChanges();
    }

    /*
     * RuneLite fires ItemDespawned when a ground item disappears.
     *
     * If that rune then appears in our combined inventory+pouch total within
     * the next few ticks, treat that increase as a pickup rather than crafting.
     */
    @Subscribe
    public void onItemDespawned(ItemDespawned event)
    {
        if (!gotrGameActive)
        {
            return;
        }

        TileItem item = event.getItem();

        if (item == null)
        {
            return;
        }

        int itemId = item.getId();

        if (!runeNames.containsKey(itemId))
        {
            return;
        }

        int quantity = item.getQuantity();

        if (quantity <= 0)
        {
            return;
        }

        pendingGroundPickups.merge(
                itemId,
                quantity,
                Integer::sum
        );

        pendingGroundPickupExpiry.put(
                itemId,
                client.getTickCount() + GROUND_PICKUP_EXPIRY_TICKS
        );
    }

    private void processRuneChanges()
    {
        Map<Integer, Integer> newRuneCounts = getCombinedRuneCounts();

        if (isBankOpen())
        {
            previousRuneCounts.clear();
            previousRuneCounts.putAll(newRuneCounts);
            return;
        }

        for (Map.Entry<Integer, String> rune : runeNames.entrySet())
        {
            int itemId = rune.getKey();
            String runeName = rune.getValue();

            int previousAmount =
                    previousRuneCounts.getOrDefault(itemId, 0);

            int newAmount =
                    newRuneCounts.getOrDefault(itemId, 0);

            int gained = newAmount - previousAmount;

            if (gained <= 0)
            {
                continue;
            }

            /*
             * Remove any amount that appears to have come from a recently
             * despawned ground-rune stack.
             */
            int pendingPickup =
                    pendingGroundPickups.getOrDefault(itemId, 0);

            if (pendingPickup > 0)
            {
                int ignored = Math.min(
                        gained,
                        pendingPickup
                );

                gained -= ignored;
                pendingPickup -= ignored;

                if (pendingPickup <= 0)
                {
                    pendingGroundPickups.remove(itemId);
                    pendingGroundPickupExpiry.remove(itemId);
                }
                else
                {
                    pendingGroundPickups.put(
                            itemId,
                            pendingPickup
                    );
                }
            }

            if (gained > 0)
            {
                currentGameTotals.merge(
                        runeName,
                        gained,
                        Integer::sum
                );

                sessionTotals.merge(
                        runeName,
                        gained,
                        Integer::sum
                );
            }
        }

        previousRuneCounts.clear();
        previousRuneCounts.putAll(newRuneCounts);

        refreshPanel();
    }

    private void expireOldGroundPickups()
    {
        int currentTick = client.getTickCount();

        Iterator<Map.Entry<Integer, Integer>> iterator =
                pendingGroundPickupExpiry.entrySet().iterator();

        while (iterator.hasNext())
        {
            Map.Entry<Integer, Integer> entry =
                    iterator.next();

            if (currentTick > entry.getValue())
            {
                pendingGroundPickups.remove(entry.getKey());
                iterator.remove();
            }
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE)
        {
            return;
        }

        String message = Text.removeTags(event.getMessage())
                .toLowerCase()
                .trim();

        if (message.contains("the rift becomes active"))
        {
            waitingForNextGameStart = false;

            beginGameTracking();
            return;
        }

        boolean gameCompletedMessage =
                message.contains(
                        "the great guardian successfully closed the rift"
                )
                        || message.contains(
                        "the rift has been subdued"
                );

        if (!gameCompletedMessage || !gotrGameActive)
        {
            return;
        }

        int currentTick = client.getTickCount();

        if (lastCompletedGameTick != -1
                && currentTick - lastCompletedGameTick <= 2)
        {
            return;
        }

        lastCompletedGameTick = currentTick;

        completeGameAutomatically();
    }

    private void beginGameTracking()
    {
        if (gotrGameActive)
        {
            return;
        }

        gotrGameActive = true;
        waitingForNextGameStart = false;

        clearCurrentGameTotals();
        snapshotCurrentRunes();

        gotrHudWasVisible = isGotrHudVisible();

        refreshPanel();

        client.addChatMessage(
                ChatMessageType.GAMEMESSAGE,
                "",
                "GOTR Rune Tracker: Game tracking started.",
                null
        );
    }

    private void completeGameAutomatically()
    {
        for (String runeName : runeNames.values())
        {
            completedGameTotals.merge(
                    runeName,
                    currentGameTotals.getOrDefault(runeName, 0),
                    Integer::sum
            );
        }

        gamesCompleted++;

        gotrGameActive = false;
        waitingForNextGameStart = true;
        gotrHudWasVisible = isGotrHudVisible();

        snapshotCurrentRunes();

        refreshPanel();

        client.addChatMessage(
                ChatMessageType.GAMEMESSAGE,
                "",
                "GOTR Rune Tracker: Game completed! Total games: "
                        + gamesCompleted,
                null
        );
    }

    private void startNewGame()
    {
        clientThread.invokeLater(() ->
        {
            clearCurrentGameTotals();

            snapshotCurrentRunes();

            gotrGameActive = isGotrHudVisible();
            waitingForNextGameStart = false;
            gotrHudWasVisible = isGotrHudVisible();

            refreshPanel();

            client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    "GOTR Rune Tracker: Current game manually reset.",
                    null
            );
        });
    }

    private void resetSession()
    {
        clientThread.invokeLater(() ->
        {
            gamesCompleted = 0;
            lastCompletedGameTick = -1;

            clearCurrentGameTotals();

            for (String runeName : runeNames.values())
            {
                sessionTotals.put(runeName, 0);
                completedGameTotals.put(runeName, 0);
            }

            gotrGameActive = false;
            waitingForNextGameStart = false;
            gotrHudWasVisible = isGotrHudVisible();

            snapshotCurrentRunes();

            refreshPanel();

            client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    "GOTR Rune Tracker: Session reset.",
                    null
            );
        });
    }

